import RNA, random, sys, json

target='....((((..(((((..((((..((((.....))))((((((...))).)))))))((((((.((.((.(((((....)).)))))))(((((.((.((.((....))))))(((((.(((....)).))).)))..)).)))))).))))))))(((.(((.(((.((((....))))))))))((((((((...))).)).))).)))))))'
n=len(target)

stack=[]
pairs={}
for i,c in enumerate(target):
    if c=='(':
        stack.append(i)
    elif c==')':
        j=stack.pop()
        pairs[j]=i
        pairs[i]=j

cur='UGCUAGCGCCCUUAGACUUUGAUCUGGCCAAACCAGCUGACUUCCAGUCCAGCAAAGCUUUUCGUACGAUGGGUCAUGACUCCACGACGCUUGCGGGUUACGCCCCUGAACUUGCUCUAGAGAAUUCGUGAAGCGGGCGAGGCGGGCGGUCUAAGAAUCUCCGCAUUCUAAAUGAUUAGAUGGGAUCGAGCCGACACGGACUACGAAAUUUGCU'
assert len(cur)==214

def diagnose(seq):
    fc=RNA.fold_compound(seq)
    mfe,_=fc.mfe()
    if mfe==target:
        return 0, [], [], mfe
    # parse mfe pairs
    st=[]; mpairs={}
    for i,c in enumerate(mfe):
        if c=='(': st.append(i)
        elif c==')':
            j=st.pop(); mpairs[j]=i; mpairs[i]=j
    # parse target pairs
    tpairs={}
    st=[]
    for i,c in enumerate(target):
        if c=='(': st.append(i)
        elif c==')':
            j=st.pop(); tpairs[j]=i; tpairs[i]=j
    missing=[]
    seen=set()
    for i,j in tpairs.items():
        if i<j and mpairs.get(i)!=j:
            missing.append((i,j))
    spurious=[]
    for i,j in mpairs.items():
        if i<j and tpairs.get(i)!=j:
            spurious.append((i,j))
    bd=RNA.bp_distance(mfe,target)
    return bd, missing, spurious, mfe

bd,missing,spurious,mfe=diagnose(cur)
sys.stderr.write(f'start bd {bd} miss {len(missing)} spur {len(spurious)}\n'); sys.stderr.flush()

best=cur; best_bd=bd
random.seed(123)

# focus positions = missing+spurious pair members + neighbors
def focus_set(missing,spurious):
    fs=set()
    for i,j in missing+spurious:
        for p in (i-1,i,i+1,j-1,j,j+1):
            if 0<=p<n: fs.add(p)
    return list(fs)

# Try targeted repair: for each missing pair, ensure G-C/C-G; for each spurious, introduce mismatch
def targeted_repair(seq, missing, spurious):
    s=list(seq)
    for i,j in missing:
        # strengthen: make G-C
        s[i]='G'; s[j]='C'
    for i,j in spurious:
        # break: make one of them a mismatch to the other
        # only break if not a target pair partner
        if i in pairs and pairs[i]==j:
            continue
        # set j to non-complement of i
        comp={'A':'U','U':'A','G':'C','C':'G'}
        # set j = same as i (guaranteed non-WC for A/G; for U/C wobble possible)
        s[j]=s[i]
    return ''.join(s)

for round in range(50):
    # targeted repair then hill-climb on focus
    cur2=targeted_repair(cur,missing,spurious)
    bd2,m2,s2,mfe2=diagnose(cur2)
    if bd2<best_bd:
        best_bd=bd2; best=cur2
        sys.stderr.write(f'round {round} targeted bd {bd2}\n'); sys.stderr.flush()
    cur=cur2; bd=bd2; missing=m2; spurious=s2
    if bd==0:
        sys.stderr.write('SOLVED targeted\n'); sys.stderr.flush()
        break
    # hill climb on focus
    fs=focus_set(missing,spurious)
    for it in range(30000):
        s=list(cur)
        nmut=random.choice([1,2,3])
        for _ in range(nmut):
            p=random.choice(fs)
            s[p]=random.choice('ACGU')
        s=''.join(s)
        d,mm,ss,mfe=diagnose(s)
        if d<bd or (d==bd and random.random()<0.2):
            cur=s; bd=d; missing=mm; spurious=ss
            if bd<best_bd:
                best_bd=bd; best=cur
                sys.stderr.write(f'round {round} it {it} bd {bd}\n'); sys.stderr.flush()
        if bd==0: break
    if bd==0:
        sys.stderr.write('SOLVED hill\n'); sys.stderr.flush()
        break

sys.stderr.write(f'final best bd {best_bd}\n'); sys.stderr.flush()
print(best)
with open('/tmp/best_seq.txt','w') as f: f.write(best)
